<script module lang="ts">
/**
 * Single-line text entry (`design/components/input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import {
  Icon,
  agentFill,
  agentMember,
  joinSlot,
  useControlRef,
  watchEffect,
  type ControlRef,
  type IconRole,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/input.module.css'

export type InputType = NonNullable<InputProps['type']>

export interface InputProps {
  'aria-describedby'?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  'aria-label'?: string
  /**
   * The id of a label elsewhere on the page, such as `SettingsRow`'s one label for a whole row.
   */
  'aria-labelledby'?: string
  'aria-required'?: boolean
  autoComplete?: string
  /**
   * Native passthrough, for surfaces that already moved the user (a dialog's first field). Never
   * use it to take focus when a page loads.
   */
  autoFocus?: boolean
  /**
   * Shows a clear button while the field is non-empty. Clearing fires `onChange('')`.
   */
  clearable?: boolean
  /**
   * The clear button's accessible name. Defaults to `Clear`. Localized hosts pass their own.
   */
  clearLabel?: string
  /**
   * The native `<input>` itself, for an application binding that must read or restore state only
   * the element has, such as a caret or a selection, without a `querySelector` into the frame.
   * Merged with the member's own ref, so both get the same node, and `null` on unmount. Accepts
   * callback and object refs.
   */
  controlRef?: ControlRef<HTMLInputElement | null>
  defaultValue?: string
  disabled?: boolean
  /**
   * The text is typed exactly: nothing corrects it, capitalises it or checks its spelling. For
   * text that must match letter for letter, such as a typed confirmation's phrase, because a
   * correction can change it while it is typed.
   */
  exact?: boolean
  /**
   * Leading, decorative.
   */
  icon?: IconRole
  id?: string
  invalid?: boolean
  max?: number
  maxLength?: number
  /**
   * `type="number"` only. Native passthrough, so the platform handles clamping and stepping.
   */
  min?: number
  name?: string
  /**
   * For touched validation, where apps mark a field dirty on leave. Native passthrough.
   */
  onBlur?: (event: FocusEvent) => void
  onChange?: (value: string, event: Event) => void
  /**
   * IME composition end. `event.data` is the committed text.
   */
  onCompositionEnd?: (event: CompositionEvent) => void
  /**
   * Native passthrough for IME composition start. Composition events arrive as the platform
   * fires them, never suppressed and never repeated as a second change, so a binding that must
   * not commit mid-composition can wait between the two.
   */
  onCompositionStart?: (event: CompositionEvent) => void
  onFocus?: (event: FocusEvent) => void
  /**
   * Native passthrough: the selection moved (caret or range, by keyboard or pointer).
   * `selectionStart`, `selectionEnd` and `selectionDirection` are on `event.currentTarget`. The
   * member never moves the selection itself. Never fires for `email` or `number`, because the
   * platform gives those types no selection API.
   */
  onSelect?: (event: Event) => void
  placeholder?: string
  /**
   * Static text inside the frame, such as a currency mark, a unit or a domain. Strings only,
   * because a node here would duplicate `trailing`. They are `aria-hidden` and not part of the
   * value, so a unit that matters belongs in the label or description. The affix is only its
   * visual form.
   */
  prefix?: string
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  step?: number
  suffix?: string
  /**
   * Slot for a vocabulary element, such as a Badge or a ghost icon Button.
   */
  trailing?: Snippet
  type?: 'number' | 'search' | 'text' | 'email' | 'password' | 'url' | 'tel'
  value?: string
}
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  autoComplete,
  autoFocus = false,
  clearable = false,
  clearLabel = 'Clear',
  controlRef,
  defaultValue,
  disabled = false,
  exact = false,
  icon,
  id: idOwn,
  invalid: invalidOwn = false,
  max,
  maxLength,
  min,
  name,
  onBlur,
  onChange,
  onCompositionEnd,
  onCompositionStart,
  onFocus,
  onSelect,
  placeholder,
  prefix,
  readOnly = false,
  size = 'md',
  step,
  suffix,
  trailing,
  type = 'text',
  value,
}: InputProps = $props()
const joined = joinSlot(undefined, () => ({ disabled: disabled, name: name, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
const slots = {
  get trailing() {
    return trailing
  },
}
// svelte-ignore state_referenced_locally
let draft = $state(defaultValue ?? '')
let control = $state<HTMLInputElement | null>(null)
const current = $derived(value ?? draft)
const showClear = $derived(clearable && current !== '' && !disabled && !readOnly)
useControlRef(
  () => controlRef,
  () => control,
)
const effect1 = () => {
  autoFocus && control?.focus()
}
watchEffect(effect1)
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'Input',
    element: () => control,
    state: () => ({ value: current, disabled: disabled, invalid: invalid, readonly: readOnly }),
    actions: {
      fill: {
        argument: 'text',
        run: (value) =>
          (() => {
            if (type === 'password')
              throw new Error('A person types a password; an agent does not.')
            if (readOnly) throw new Error('The field is read-only.')
            agentFill(control, value)
          })(),
      },
      clear: () =>
        (() => {
          if (readOnly) throw new Error('The field is read-only.')
          agentFill(control, '')
        })(),
    },
  })
  release2 = () => {
    ran()
  }
}
watchEffect(effect2)
onDestroy(() => release2?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    class={styles.field}
    data-size={size}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(invalid) ? '' : undefined}
    data-readonly={(readOnly) ? '' : undefined}
    data-member="input"
    onmousedown={(event) => { if (!(event.composedPath().some((node) => 'nodeName' in node && ['BUTTON', 'A', 'INPUT', 'SELECT', 'TEXTAREA'].includes(String(node.nodeName))))) (event.preventDefault(), control?.focus()) }}
    >{#if icon !== undefined}<span class={styles.leading}><Icon name={icon} {size} /></span>{/if
    }{#if prefix !== undefined}<span class={styles.affix} aria-hidden="true">{prefix}</span>{/if
    }<input
      bind:this={control}
      class={styles.input}
      {type}
      value={current}
      {placeholder}
      {disabled}
      readonly={readOnly}
      {min}
      {max}
      {step}
      {name}
      {id}
      autocomplete={(autoComplete) as never}
      autocorrect={(exact) ? 'off' : undefined}
      autocapitalize={(exact) ? 'off' : undefined}
      spellcheck={(exact) ? 'false' : undefined}
      maxlength={maxLength}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledby}
      aria-describedby={ariaDescribedby}
      aria-required={ariaRequired}
      aria-invalid={(invalid) ? true : undefined}
      oninput={(event) => { (draft = control?.value ?? '', onChange?.(draft, event)) }}
      onblur={(event) => { onBlur?.(event) }}
      onfocus={(event) => { onFocus?.(event) }}
      onselect={(event) => { onSelect?.(event) }}
      oncompositionstart={(event) => { onCompositionStart?.(event) }}
      oncompositionend={(event) => { onCompositionEnd?.(event) }}
    />{#if suffix !== undefined}<span class={styles.affix} aria-hidden="true">{suffix}</span>{/if
    }{#if showClear
      }<button
        class={styles.clear}
        type="button"
        aria-label={clearLabel}
        onclick={(event) => { (draft = '', onChange?.('', event), control?.focus()) }}
        ><Icon name="clear" {size}
      /></button
    >{/if
    }{#if slots.trailing}<span class={styles.trailing}>{@render trailing?.()}</span>{/if
  }</div
>{/if
}{@render joined.end?.()}
